class DwgCompoundWriteTestAccess final {
public:
  static void setVersion(dwgRW &writer, DRW::Version version) {
    writer.version = version;
  }

  static void failNextSeqEnd(dwgRW &writer) {
    writer.m_failNextCompoundSeqEndForTest = true;
  }

  static void failAfterFirstDeferredTableRecord(dwgRW &writer) {
    writer.setDwgWriteFailurePointForTest(
        dwgRW::DwgWriteFailurePoint::AfterFirstDeferredTableRecord);
  }

  static void failAfterFirstBlockRecord(dwgRW &writer) {
    writer.setDwgWriteFailurePointForTest(
        dwgRW::DwgWriteFailurePoint::AfterFirstBlockRecord);
  }

  static void failBeforeEndBlockFrame(dwgRW &writer) {
    writer.setDwgWriteFailurePointForTest(
        dwgRW::DwgWriteFailurePoint::BeforeEndBlockFrame);
  }

  static void failAfterEndBlockFrame(dwgRW &writer) {
    writer.setDwgWriteFailurePointForTest(
        dwgRW::DwgWriteFailurePoint::AfterEndBlockFrame);
  }

  static void failAfterFirstBlockOwnedEntity(dwgRW &writer) {
    writer.setDwgWriteFailurePointForTest(
        dwgRW::DwgWriteFailurePoint::AfterFirstBlockOwnedEntity);
  }

  static bool writeDwgObjects(dwgRW &writer) {
    return writer.writeDwgObjectsForTest();
  }

  static bool emitDeferredBlockControl(dwgRW &writer) {
    return writer.emitDeferredBlockControlForTest();
  }
};

class DwgWriteFailureTestAccess final {
public:
  using Registry = RS_FilterDXFRW_DwgWriteIdentityRegistry;
  using SourceKind = Registry::DwgWriteSourceKind;
  using ClassFrameDescriptor = Registry::DwgClassFrameAdmission;
  using OpaqueTableFailure = RS_FilterDXFRW::DwgOpaqueTableFailure;
  using OpaqueTableFailureKind = RS_FilterDXFRW::DwgOpaqueTableFailureKind;
  using OpaqueTableFailurePhase = RS_FilterDXFRW::DwgOpaqueTableFailurePhase;

  static void latch(RS_FilterDXFRW &filter) { filter.m_writeFailed = true; }

  static bool isTableRecordCommitted(const RS_FilterDXFRW &filter,
                                     std::uint32_t sourceHandle) {
    std::uint32_t outputHandle = 0;
    return filter.lookupDwgWriteIdentity(
               Registry::DwgWriteSourceKind::TableRecord, sourceHandle,
               &outputHandle) == Registry::DwgWriteIdentityLookup::Committed;
  }

  static bool isTableRecordSelected(const RS_FilterDXFRW &filter,
                                    std::uint32_t sourceHandle) {
    std::uint32_t outputHandle = 0;
    return filter.lookupDwgWriteIdentity(
               Registry::DwgWriteSourceKind::TableRecord, sourceHandle,
               &outputHandle) == Registry::DwgWriteIdentityLookup::Selected;
  }

  static bool injectCommittedIdentity(RS_FilterDXFRW &filter,
                                      Registry::DwgWriteSourceKind kind,
                                      std::uint32_t sourceHandle,
                                      std::uint32_t outputHandle) {
    filter.noteDwgWriteSourceKind(sourceHandle, kind);
    return filter.reserveDwgWriteIdentity(kind, sourceHandle, outputHandle) &&
           filter.selectDwgWriteIdentity(kind, sourceHandle, outputHandle) &&
           filter.commitDwgWriteIdentity(kind, outputHandle);
  }

  static bool isIdentityCommitted(const RS_FilterDXFRW &filter,
                                  Registry::DwgWriteSourceKind kind,
                                  std::uint32_t outputHandle) {
    return filter.isDwgWriteIdentityCommitted(kind, outputHandle);
  }

  static bool isSourceIdentityCommitted(const RS_FilterDXFRW &filter,
                                        Registry::DwgWriteSourceKind kind,
                                        std::uint32_t sourceHandle) {
    std::uint32_t outputHandle = 0;
    return filter.lookupDwgWriteIdentity(kind, sourceHandle, &outputHandle) ==
           Registry::DwgWriteIdentityLookup::Committed;
  }

  static bool admitClassFrame(RS_FilterDXFRW &filter, SourceKind kind,
                              std::uint32_t sourceHandle,
                              std::uint32_t outputHandle,
                              std::uint16_t classNumber) {
    return filter.admitDwgClassFrame(kind, sourceHandle, outputHandle,
                                     classNumber);
  }

  static bool admitClassFrameDescriptor(RS_FilterDXFRW &filter, SourceKind kind,
                                        std::uint32_t sourceHandle,
                                        std::uint32_t outputHandle,
                                        std::uint16_t classNumber,
                                        std::uint32_t sourceOrdinal,
                                        DRW::Version version) {
    return filter.admitDwgClassFrameDescriptor(
        kind, sourceHandle, outputHandle, classNumber, sourceOrdinal, version);
  }

  static bool
  getClassFrameDescriptor(const RS_FilterDXFRW &filter, SourceKind kind,
                          std::uint32_t sourceHandle,
                          std::uint32_t sourceOrdinal,
                          Registry::DwgClassFrameAdmission &descriptor) {
    return filter.getDwgClassFrameDescriptor(kind, sourceHandle, sourceOrdinal,
                                             descriptor);
  }

  static bool findClassFrame(const RS_FilterDXFRW &filter, SourceKind kind,
                             std::uint32_t sourceHandle,
                             std::uint32_t outputHandle,
                             std::uint16_t &classNumber, bool &committed) {
    return filter.findDwgClassFrameAdmission(kind, sourceHandle, outputHandle,
                                             classNumber, committed);
  }

  static bool prepareDataStoragePlan(RS_FilterDXFRW &filter,
                                     RS_Graphic &graphic,
                                     DRW::Version version) {
    filter.m_graphic = &graphic;
    return filter.prepareDwgDataStorageReplayPlan(version);
  }

  static bool freezeDataStoragePlanForTest(RS_FilterDXFRW &filter) {
    for (auto &decision : filter.m_dwgDataStorageReplayPlan.decisions) {
      if (decision.admissionToken == 0)
        decision.admissionToken = filter.m_nextDwgDataStorageAdmissionToken++;
    }
    filter.m_dwgDataStorageReplayPlan.frozen = true;
    return filter.m_dwgDataStorageReplayPlan.valid;
  }

  static bool freezeDataStoragePlan(RS_FilterDXFRW &filter) {
    return filter.freezeDwgDataStorageReplayPlan();
  }

  static std::uint64_t dataStoragePlanGeneration(const RS_FilterDXFRW &filter) {
    return filter.m_dwgDataStorageReplayPlan.generation;
  }

  static std::size_t
  firstDataStorageRawSectionIndex(const RS_FilterDXFRW &filter) {
    return filter.m_dwgDataStorageReplayPlan.rawSectionIndexes.empty()
               ? std::numeric_limits<std::size_t>::max()
               : *filter.m_dwgDataStorageReplayPlan.rawSectionIndexes.begin();
  }

  static std::size_t firstDataStorageRecordIndex(const RS_FilterDXFRW &filter) {
    return filter.m_dwgDataStorageReplayPlan.decisions.empty()
               ? std::numeric_limits<std::size_t>::max()
               : filter.m_dwgDataStorageReplayPlan.decisions.front()
                     .recordIndex;
  }

  static bool firstDataStorageDecisionIsRaw(const RS_FilterDXFRW &filter) {
    return !filter.m_dwgDataStorageReplayPlan.decisions.empty() &&
           filter.m_dwgDataStorageReplayPlan.decisions.front().decision ==
               RS_FilterDXFRW::DwgDataStorageDecision::EmitRaw;
  }

  static std::size_t dataStorageDecisionCount(const RS_FilterDXFRW &filter) {
    return filter.m_dwgDataStorageReplayPlan.decisions.size();
  }

  static RS_FilterDXFRW::DwgDataStorageIdentityStatus
  resolveDataStorageIdentity(std::uint32_t ownerHandle,
                             std::uint64_t storageHandle, bool hasStorageHandle,
                             const std::string &storageHandleKey,
                             bool hasStorageHandleKey) {
    return RS_FilterDXFRW::resolveDwgDataStorageIdentity(
               ownerHandle, storageHandle, hasStorageHandle, storageHandleKey,
               hasStorageHandleKey)
        .status;
  }

  static void recordDataStorageReceipt(RS_FilterDXFRW &filter,
                                       std::size_t rawSectionIndex,
                                       std::size_t recordIndex,
                                       std::uint64_t generation) {
    RS_FilterDXFRW::DwgDataStorageSectionReceipt receipt;
    receipt.generation = generation;
    receipt.rawSectionIndex = rawSectionIndex;
    receipt.recordIndexes.insert(recordIndex);
    const auto &section = filter.m_graphic->dwgAdvancedMetadata()
                              .rawDwgSections()[rawSectionIndex];
    receipt.sourceRows.insert(filter.makeDwgDataStorageSourceRowKey(
        section.name, section.version, rawSectionIndex, recordIndex));
    filter.m_dwgDataStorageSectionReceipts[rawSectionIndex] =
        std::move(receipt);
  }

  static void recordDataStorageCommit(RS_FilterDXFRW &filter,
                                      std::uint32_t ownerHandle, bool raw) {
    filter.m_dwgDataStorageCommittedKinds[ownerHandle] =
        raw ? RS_FilterDXFRW::DwgDataStorageCarrier::Kind::Raw
            : RS_FilterDXFRW::DwgDataStorageCarrier::Kind::Typed;
    const auto decisionIt =
        filter.m_dwgDataStorageReplayPlan.decisionByOwner.find(ownerHandle);
    if (decisionIt == filter.m_dwgDataStorageReplayPlan.decisionByOwner.end() ||
        decisionIt->second >=
            filter.m_dwgDataStorageReplayPlan.decisions.size())
      return;
    const auto &decision =
        filter.m_dwgDataStorageReplayPlan.decisions[decisionIt->second];
    RS_FilterDXFRW::DwgDataStorageCommitReceipt receipt;
    receipt.generation = filter.m_dwgDataStorageReplayPlan.generation;
    receipt.carrierIndex = decision.selectedCarrierIndex;
    receipt.kind = filter.m_dwgDataStorageCommittedKinds[ownerHandle];
    receipt.binding = decision.binding;
    receipt.phase = decision.selectedPhase;
    receipt.capability = decision.selectedCapability;
    receipt.state = RS_FilterDXFRW::DwgDataStorageLedgerState::SectionCommitted;
    receipt.sourceKind = RS_FilterDXFRW::DwgWriteSourceKind::Object;
    receipt.expectedBlockOwner = DRW::NoHandle;
    if (decision.selectedCarrierIndex <
        filter.m_dwgDataStorageReplayPlan.carriers.size()) {
      const auto &carrier = filter.m_dwgDataStorageReplayPlan
                                .carriers[decision.selectedCarrierIndex];
      receipt.writerFamily = carrier.writerFamily;
      receipt.className = carrier.className;
      receipt.recordName = carrier.recordName;
      receipt.classNumber = carrier.classNumber;
      receipt.admissionToken = decision.admissionToken;
      receipt.sourceRow = decision.sourceRow;
      receipt.classAdmitted = !carrier.className.empty() || raw;
      if (carrier.kind == RS_FilterDXFRW::DwgDataStorageCarrier::Kind::Raw &&
          carrier.rawObjectIndex <
              filter.m_graphic->dwgAdvancedMetadata().rawObjects().size()) {
        const auto &rawObject = filter.m_graphic->dwgAdvancedMetadata()
                                    .rawObjects()[carrier.rawObjectIndex];
        receipt.sourceKind = rawObject.isEntity
                                 ? RS_FilterDXFRW::DwgWriteSourceKind::Entity
                                 : RS_FilterDXFRW::DwgWriteSourceKind::Object;
        receipt.expectedBlockOwner = rawObject.blockOwnerHandle != DRW::NoHandle
                                         ? rawObject.blockOwnerHandle
                                         : rawObject.parentHandle;
        receipt.frame.classNumber =
            static_cast<std::uint16_t>(rawObject.objectType);
      }
    }
    receipt.sourceHandle = ownerHandle;
    receipt.outputHandle = ownerHandle;
    receipt.objectCommitted = true;
    receipt.sectionCommitted = true;
    receipt.frameValid = true;
    receipt.frame.valid = true;
    receipt.frame.generation = 1;
    receipt.frame.objectHandle = ownerHandle;
    receipt.frame.version = filter.m_dwgDataStorageReplayPlan.version;
    receipt.writerClassNumber = receipt.frame.classNumber;
    receipt.frame.admissionToken = receipt.admissionToken;
    filter.m_dwgDataStorageCommitReceipts[ownerHandle] = std::move(receipt);
  }

  static void corruptFirstDataStorageCommitCarrier(RS_FilterDXFRW &filter) {
    if (!filter.m_dwgDataStorageCommitReceipts.empty())
      filter.m_dwgDataStorageCommitReceipts.begin()->second.carrierIndex =
          std::numeric_limits<std::size_t>::max();
  }

  static bool validateDataStorageReceipts(const RS_FilterDXFRW &filter,
                                          DRW::Version version) {
    return filter.validateDwgDataStorageReplayReceipts(version);
  }

  static bool validateDataStorageAdmissionSummary(const RS_FilterDXFRW &filter,
                                                  bool requireClassAdmission) {
    return filter.validateDwgDataStorageAdmissionSummary(requireClassAdmission);
  }

  static bool validateDataStoragePreflight(const RS_FilterDXFRW &filter,
                                           DRW::Version version) {
    return filter.validateDwgDataStoragePreflight(version);
  }

  static std::size_t
  dataStorageAdmissionSummarySize(const RS_FilterDXFRW &filter) {
    return filter.m_dwgDataStorageAdmissionSummary.entries.size();
  }

  static bool recordDataStorageClassAdmission(RS_FilterDXFRW &filter,
                                              std::uint32_t sourceHandle,
                                              bool raw) {
    return filter.recordDwgDataStorageClassAdmission(
        sourceHandle, raw ? RS_FilterDXFRW::DwgDataStorageCarrier::Kind::Raw
                          : RS_FilterDXFRW::DwgDataStorageCarrier::Kind::Typed);
  }

  static void clearDataStorageCommittedKindIndex(RS_FilterDXFRW &filter) {
    filter.m_dwgDataStorageCommittedKinds.clear();
  }

  static void corruptFirstDataStorageSourceRow(RS_FilterDXFRW &filter) {
    filter.m_dwgDataStorageCommitReceipts.begin()
        ->second.sourceRow.recordIndex++;
  }

  static void bindWriter(RS_FilterDXFRW &filter, dwgRW *writer) {
    filter.m_dwgW = writer;
  }

  static void setPostClassesHook(RS_FilterDXFRW &filter,
                                 std::function<void()> hook) {
    filter.m_dwgPostClassesTestHook = std::move(hook);
  }

  static void setPostObjectsHook(RS_FilterDXFRW &filter,
                                 std::function<void()> hook) {
    filter.m_dwgPostObjectsTestHook = std::move(hook);
  }

  static bool corruptFirstFieldFrame(RS_FilterDXFRW &filter) {
    if (filter.m_dwgFieldWritePlan.fieldCandidates.empty())
      return false;
    ++filter.m_dwgFieldWritePlan.fieldCandidates.front().frame.generation;
    return true;
  }

  static bool corruptFieldChildReceipt(RS_FilterDXFRW &filter) {
    const auto receipt = std::find_if(
        filter.m_dwgWriteReferenceReceipts.begin(),
        filter.m_dwgWriteReferenceReceipts.end(), [](const auto &candidate) {
          return candidate.referenceName == "FIELD child";
        });
    if (receipt == filter.m_dwgWriteReferenceReceipts.end())
      return false;
    receipt->wireHandleCode = DRW::DwgSoftPointer;
    return true;
  }

  static dwgRW *activeWriter(RS_FilterDXFRW &filter) { return filter.m_dwgW; }

  static void failNextFieldClassRegistration(dwgRW &writer) {
    writer.m_failNextFieldClassRegistrationForTest = true;
  }

  static bool fieldPlanClassesAdmitted(const RS_FilterDXFRW &filter) {
    return filter.m_dwgFieldWritePlan.classesAdmitted;
  }

  static std::size_t fieldCandidateCount(const RS_FilterDXFRW &filter) {
    return filter.m_dwgFieldWritePlan.fieldCandidates.size();
  }

  static std::size_t fieldListCandidateCount(const RS_FilterDXFRW &filter) {
    return filter.m_dwgFieldWritePlan.fieldListCandidates.size();
  }

  static bool fieldCandidateClassAdmitted(const RS_FilterDXFRW &filter,
                                          std::size_t index) {
    return index < filter.m_dwgFieldWritePlan.fieldCandidates.size() &&
           filter.m_dwgFieldWritePlan.fieldCandidates[index].classAdmitted;
  }

  static bool fieldCandidateObjectEmitted(const RS_FilterDXFRW &filter,
                                          std::size_t index) {
    return index < filter.m_dwgFieldWritePlan.fieldCandidates.size() &&
           filter.m_dwgFieldWritePlan.fieldCandidates[index].objectEmitted;
  }

  static bool fieldListCandidateClassAdmitted(const RS_FilterDXFRW &filter,
                                              std::size_t index) {
    return index < filter.m_dwgFieldWritePlan.fieldListCandidates.size() &&
           filter.m_dwgFieldWritePlan.fieldListCandidates[index].classAdmitted;
  }

  static bool fieldListCandidateObjectEmitted(const RS_FilterDXFRW &filter,
                                              std::size_t index) {
    return index < filter.m_dwgFieldWritePlan.fieldListCandidates.size() &&
           filter.m_dwgFieldWritePlan.fieldListCandidates[index].objectEmitted;
  }

  static bool opaqueTablePreflightFailure(const RS_FilterDXFRW &filter,
                                          std::size_t rawObjectIndex,
                                          OpaqueTableFailure &failure) {
    const auto it =
        filter.m_dwgExportAdmissionPlan.opaqueTableRecordIndexes.find(
            rawObjectIndex);
    if (it == filter.m_dwgExportAdmissionPlan.opaqueTableRecordIndexes.end() ||
        !it->second.preflightFailure.has_value()) {
      return false;
    }
    failure = *it->second.preflightFailure;
    return true;
  }

  static bool opaqueTableRuntimeFailure(const RS_FilterDXFRW &filter,
                                        std::size_t rawObjectIndex,
                                        OpaqueTableFailure &failure) {
    const auto it = filter.m_dwgOpaqueTableRuntimeFailures.find(rawObjectIndex);
    if (it == filter.m_dwgOpaqueTableRuntimeFailures.end())
      return false;
    failure = it->second;
    return true;
  }

  static std::size_t objectOccurrenceCount(const RS_FilterDXFRW &filter) {
    return filter.m_dwgWriteObjectOccurrencesByOutput.size();
  }

  static bool hasObjectOccurrences(const RS_FilterDXFRW &filter,
                                   std::uint32_t outputHandle) {
    return filter.findDwgWriteObjectOccurrences(outputHandle) != nullptr;
  }

  static std::size_t committedIdentityCount(const RS_FilterDXFRW &filter,
                                            SourceKind kind) {
    return static_cast<std::size_t>(std::count_if(
        filter.m_dwgWriteIdentityByOutput.cbegin(),
        filter.m_dwgWriteIdentityByOutput.cend(), [kind](const auto &item) {
          return item.first.kind == kind &&
                 item.second.state ==
                     Registry::DwgWriteIdentityState::Committed;
        }));
  }

  static bool recordDataStorageObjectCommit(RS_FilterDXFRW &filter,
                                            std::uint32_t sourceHandle,
                                            bool raw) {
    const auto decisionIt =
        filter.m_dwgDataStorageReplayPlan.decisionByOwner.find(sourceHandle);
    if (decisionIt == filter.m_dwgDataStorageReplayPlan.decisionByOwner.end() ||
        decisionIt->second >=
            filter.m_dwgDataStorageReplayPlan.decisions.size())
      return false;
    const auto &decision =
        filter.m_dwgDataStorageReplayPlan.decisions[decisionIt->second];
    const std::uint32_t outputHandle =
        filter.resolveDwgWriteHandle(sourceHandle);
    DRW::DwgObjectFrameReceipt frame;
    frame.valid = true;
    frame.objectHandle = outputHandle;
    frame.version = filter.m_dwgDataStorageReplayPlan.version;
    frame.admissionToken = decision.admissionToken;
    const auto carrierKind =
        raw ? RS_FilterDXFRW::DwgDataStorageCarrier::Kind::Raw
            : RS_FilterDXFRW::DwgDataStorageCarrier::Kind::Typed;
    RS_FilterDXFRW::DwgWriteSourceKind sourceKind =
        RS_FilterDXFRW::DwgWriteSourceKind::Object;
    if (decision.selectedCarrierIndex <
        filter.m_dwgDataStorageReplayPlan.carriers.size()) {
      const auto &carrier = filter.m_dwgDataStorageReplayPlan
                                .carriers[decision.selectedCarrierIndex];
      frame.classNumber = carrier.classNumber;
      if (carrier.kind == RS_FilterDXFRW::DwgDataStorageCarrier::Kind::Raw &&
          carrier.rawObjectIndex <
              filter.m_graphic->dwgAdvancedMetadata().rawObjects().size() &&
          filter.m_graphic->dwgAdvancedMetadata()
              .rawObjects()[carrier.rawObjectIndex]
              .isEntity) {
        sourceKind = RS_FilterDXFRW::DwgWriteSourceKind::Entity;
      }
      if (carrier.kind == RS_FilterDXFRW::DwgDataStorageCarrier::Kind::Raw &&
          carrier.rawObjectIndex <
              filter.m_graphic->dwgAdvancedMetadata().rawObjects().size()) {
        frame.classNumber =
            static_cast<std::uint16_t>(filter.m_graphic->dwgAdvancedMetadata()
                                           .rawObjects()[carrier.rawObjectIndex]
                                           .objectType);
      }
    }
    return filter.recordDwgDataStorageObjectCommit(
        sourceHandle, carrierKind, sourceKind, outputHandle, frame);
  }

  static void failDataStorageCommit(RS_FilterDXFRW &filter,
                                    std::uint32_t sourceHandle) {
    filter.failDwgDataStorageCommit(sourceHandle);
  }

  static bool recordDataStorageSectionCommit(RS_FilterDXFRW &filter,
                                             std::size_t rawSectionIndex,
                                             std::size_t recordIndex) {
    return filter.recordDwgDataStorageSectionCommit(
        rawSectionIndex, std::set<std::size_t>{recordIndex});
  }

  static bool recordFrame(RS_FilterDXFRW &filter, std::uint32_t outputHandle,
                          const DRW::DwgObjectFrameReceipt &frame) {
    return filter.RS_FilterDXFRW_DwgWriteIdentityRegistry::
        recordDwgWriteObjectOccurrences(outputHandle, frame);
  }

  using EntityPlanRoute = Registry::DwgEntityWritePlanRoute;
  using FixedEntityRoute = Registry::DwgFixedEntityRoute;

  static bool stageEntityPlan(RS_FilterDXFRW &filter, const RS_Entity *entity,
                              std::uint32_t sourceHandle,
                              std::uint32_t outputHandle, EntityPlanRoute route,
                              FixedEntityRoute fixedRoute,
                              std::uint16_t frameType, DRW::Version version) {
    return filter.stageDwgEntityWritePlan(entity, sourceHandle, outputHandle,
                                          route, fixedRoute, frameType,
                                          version);
  }

  static bool
  admitFixedEntityPlan(RS_FilterDXFRW &filter, const RS_Entity *entity,
                       std::uint32_t sourceHandle, std::uint32_t outputHandle,
                       FixedEntityRoute route, std::uint16_t frameType,
                       DRW::Version version) {
    return filter.admitDwgFixedEntityFrame(route, sourceHandle, outputHandle,
                                           frameType, version) &&
           filter.admitDwgEntityWritePlan(entity);
  }

  static bool commitFixedEntityPlan(RS_FilterDXFRW &filter,
                                    const RS_Entity *entity,
                                    FixedEntityRoute route,
                                    std::uint32_t sourceHandle,
                                    std::uint32_t outputHandle,
                                    const DRW::DwgObjectFrameReceipt &frame) {
    return filter.commitDwgFixedEntityFrame(route, sourceHandle, outputHandle,
                                            frame) &&
           filter.commitDwgEntityWritePlan(entity, frame);
  }

  static bool validateEntityPlans(const RS_FilterDXFRW &filter) {
    return filter.validateDwgEntityWritePlans();
  }
};
