class PublicObjectRollbackIface final : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};

  void writeObjects() override {
    REQUIRE(m_writer != nullptr);

    DRW_Line entity;
    REQUIRE(m_writer->writeLine(&entity));
    DRW_Dictionary directObject;
    directObject.handle = 0x6F0u;
    directObject.parentHandle = DRW::DwgNamedObjectsDictionaryHandle;
    REQUIRE(m_writer->writeDictionary(&directObject));
    // A direct OBJECT starts a new implicit scope; it must not leave the
    // preceding entity armed for a later rollback.
    CHECK_FALSE(m_writer->rollbackLastDwgObjectWrite());

    DRW_Dictionary first;
    first.handle = 0x700u;
    first.parentHandle = DRW::DwgNamedObjectsDictionaryHandle;
    const std::uint64_t transaction = m_writer->beginDwgWriteTransaction();
    REQUIRE(transaction != 0);
    REQUIRE(m_writer->writeDictionary(&first));
    DRW::DwgObjectFrameReceipt frame;
    REQUIRE(m_writer->getLastDwgObjectFrame(frame));
    REQUIRE(m_writer->rollbackDwgWriteTransaction(transaction));
    CHECK_FALSE(m_writer->getLastDwgObjectFrame(frame));

    DRW_Dictionary second;
    second.handle = 0x701u;
    second.parentHandle = DRW::DwgNamedObjectsDictionaryHandle;
    REQUIRE(m_writer->writeDictionary(&second));
    CHECK(second.handle != first.handle);
  }
};

