class InvalidImageForRollback final : public DRW_Image {
public:
  void makeInvalidClipPath() {
    m_clipBoundaryType = 2;
    clipPath.assign(DRW_Image::kMaxClipVertices + 1, DRW_Coord{0.0, 0.0, 0.0});
  }

  void makeValidClipPath() {
    m_clipBoundaryType = 0;
    clipPath.clear();
  }
};

class PublicImageRollbackIface final : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};

  void writeEntities() override {
    REQUIRE(m_writer != nullptr);

    InvalidImageForRollback image;
    image.makeInvalidClipPath();
    const std::string fileName = "rollback.png";
    CHECK_FALSE(m_writer->writeImage(&image, &fileName));
    CHECK(image.handle == 0);
    CHECK(m_writer->getSuccessfulEntityWriteCount() == 0);
    DRW::DwgObjectFrameReceipt frame;
    CHECK_FALSE(m_writer->getLastDwgObjectFrame(frame));

    // The failed compound write must leave the caller reusable. A valid
    // retry must publish one complete IMAGE dependency graph.
    image.makeValidClipPath();
    REQUIRE(m_writer->writeImage(&image, &fileName));
    CHECK(image.handle != 0);
    CHECK(m_writer->getSuccessfulEntityWriteCount() == 1);

    DRW_Line line;
    REQUIRE(m_writer->writeLine(&line));
    CHECK(m_writer->getSuccessfulEntityWriteCount() == 2);
  }
};

class ImageRollbackReadIface final : public EmptyIface {
public:
  int imageCount{0};
  int imageDefinitionCount{0};
  int reactorCount{0};

  void addImage(const DRW_Image *) override { ++imageCount; }
  void linkImage(const DRW_ImageDef *) override { ++imageDefinitionCount; }
  void addImageDefinitionReactor(const DRW_ImageDefinitionReactor &) override {
    ++reactorCount;
  }
};

