class SeqEndFailureIface final : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  bool m_insert{false};
  bool m_compoundFailed{false};
  bool m_trailingLineWritten{false};
  std::uint32_t m_blockRecordHandle{0};
  DRW_Line m_trailingLine;
  DRW::DwgBlockWriteResult m_blockWriteResult;

  bool finalizeDwgWriteStructure() override {
    REQUIRE(m_writer != nullptr);
    return m_writer->getEmittedDwgBlockWriteResult(m_blockWriteResult);
  }

  void writeBlocks() override {
    REQUIRE(m_writer != nullptr);
    m_blockRecordHandle =
        m_writer->defineBlock("SeqEndFailureBlock", DRW_Coord{});
    REQUIRE(m_blockRecordHandle != 0);
    REQUIRE(m_writer->beginBlockContent(m_blockRecordHandle));
  }

  void writeEntities() override {
    REQUIRE(m_writer != nullptr);

    if (m_insert) {
      DRW_Insert insert;
      insert.name = "SeqEndFailureBlock";
      insert.blockRecH.ref = m_blockRecordHandle;
      insert.parentHandle = m_blockRecordHandle;
      auto attribute = std::make_shared<DRW_Attrib>();
      attribute->tag = "TAG";
      attribute->text = "VALUE";
      attribute->height = 1.0;
      insert.attlist.push_back(std::move(attribute));
      DwgCompoundWriteTestAccess::failNextSeqEnd(*m_writer);
      m_compoundFailed = !m_writer->writeInsert(&insert);
    } else {
      DRW_Polyline polyline;
      polyline.flags = 1;
      polyline.parentHandle = m_blockRecordHandle;
      polyline.addVertex(DRW_Vertex(0.0, 0.0, 0.0, 0.0));
      polyline.addVertex(DRW_Vertex(10.0, 0.0, 0.0, 0.0));
      DwgCompoundWriteTestAccess::failNextSeqEnd(*m_writer);
      m_compoundFailed = !m_writer->writePolyline(&polyline);
    }

    m_trailingLine.basePoint = {20.0, 20.0, 0.0};
    m_trailingLine.secPoint = {30.0, 30.0, 0.0};
    m_trailingLineWritten = m_writer->writeLine(&m_trailingLine);
    REQUIRE(m_writer->endBlockContent());
  }
};

class SeqEndFailureReadIface final : public EmptyIface {
public:
  std::size_t lines{0};
  std::size_t inserts{0};
  std::size_t polylines{0};
  std::size_t vertices{0};

  void addLine(const DRW_Line &) override { ++lines; }
  void addInsert(const DRW_Insert &) override { ++inserts; }
  void addPolyline(const DRW_Polyline &) override { ++polylines; }
  void addKnot(const DRW_Entity &) override { ++vertices; }
};

class CompoundWriteFailureIface : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  std::uint32_t m_blockRecordHandle{0};
  DRW::DwgBlockWriteResult m_blockWriteResult;

  bool finalizeDwgWriteStructure() override {
    REQUIRE(m_writer != nullptr);
    return m_writer->getEmittedDwgBlockWriteResult(m_blockWriteResult);
  }

  void writeBlocks() override {
    REQUIRE(m_writer != nullptr);
    m_blockRecordHandle =
        m_writer->defineBlock("CompoundRollback", DRW_Coord{});
    REQUIRE(m_blockRecordHandle != 0);
    REQUIRE(m_writer->beginBlockContent(m_blockRecordHandle));
  }

  void writeEntities() override {
    REQUIRE(m_writer != nullptr);

    DRW_Insert insert;
    insert.attlist.push_back(std::make_shared<DRW_Attrib>());
    insert.attlist.push_back(std::make_shared<FailingAttrib>());
    CHECK_FALSE(m_writer->writeInsert(&insert));

    DRW_Polyline polyline;
    polyline.vertlist.push_back(std::make_shared<DRW_Vertex>());
    polyline.vertlist.push_back(std::make_shared<FailingVertex>());
    CHECK_FALSE(m_writer->writePolyline(&polyline));

    REQUIRE(m_writer->endBlockContent());

    CHECK_FALSE(m_writer->writeInsert(&insert));
    CHECK_FALSE(m_writer->writePolyline(&polyline));
  }
};

