void assertRegistryArc(const WholeModelRegistryIface &iface) {
  REQUIRE(iface.m_arcs.size() == 1);
  CHECK(iface.m_arcs[0].basePoint.x == Catch::Approx(50.0));
  CHECK(iface.m_arcs[0].radious == Catch::Approx(10.0));
  CHECK(iface.m_arcs[0].staangle == Catch::Approx(0.0));
  CHECK(iface.m_arcs[0].endangle == Catch::Approx(3.141592653589793));
  CHECK(iface.m_arcs[0].color == 6);
}

void assertRegistryEllipse(const WholeModelRegistryIface &iface) {
  REQUIRE(iface.m_ellipses.size() == 1);
  CHECK(iface.m_ellipses[0].basePoint.x == Catch::Approx(200.0));
  CHECK(iface.m_ellipses[0].secPoint.x == Catch::Approx(30.0));
  CHECK(iface.m_ellipses[0].ratio == Catch::Approx(0.5));
  CHECK(iface.m_ellipses[0].color == 4);
}

void assertRegistryMPolygon(const WholeModelRegistryIface &iface) {
  REQUIRE(iface.m_mpolygons.size() == 1);
  CHECK(iface.m_hatches.empty());

  const DRW_MPolygon &polygon = iface.m_mpolygons[0];
  CHECK(polygon.eType == DRW::MPOLYGON);
  CHECK(polygon.name == "SOLID");
  CHECK(polygon.solid == 1);
  CHECK(polygon.fillColorAci == 3);
  REQUIRE(polygon.looplist.size() == 1);
  const auto &loop = polygon.looplist[0];
  CHECK((loop->type & 2) == 2);
  REQUIRE_FALSE(loop->objlist.empty());
  auto *polyline = dynamic_cast<DRW_LWPolyline *>(loop->objlist[0].get());
  REQUIRE(polyline != nullptr);
  CHECK((polyline->flags & 1) == 1);
  CHECK(polyline->vertlist.size() == 4u);
}

class MPolygonOnlyIface : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  std::vector<DRW_MPolygon> m_mpolygons;
  std::vector<DRW_Hatch> m_hatches;

  void writeEntities() override {
    if (m_writer == nullptr)
      return;
    REQUIRE(writeRegistryMPolygon(*m_writer));
  }

  void addMPolygon(const DRW_MPolygon *p) override {
    if (p != nullptr)
      m_mpolygons.push_back(*p);
  }

  void addHatch(const DRW_Hatch *h) override {
    if (h != nullptr)
      m_hatches.push_back(*h);
  }
};

void assertMPolygonOnlyRead(const MPolygonOnlyIface &iface) {
  REQUIRE(iface.m_mpolygons.size() == 1);
  CHECK(iface.m_hatches.empty());

  const DRW_MPolygon &polygon = iface.m_mpolygons[0];
  CHECK(polygon.eType == DRW::MPOLYGON);
  CHECK(polygon.name == "SOLID");
  CHECK(polygon.solid == 1);
  CHECK(polygon.fillColorAci == 3);
  REQUIRE(polygon.looplist.size() == 1);
  const auto &loop = polygon.looplist[0];
  CHECK((loop->type & 2) == 2);
  REQUIRE_FALSE(loop->objlist.empty());
  auto *polyline = dynamic_cast<DRW_LWPolyline *>(loop->objlist[0].get());
  REQUIRE(polyline != nullptr);
  CHECK((polyline->flags & 1) == 1);
  CHECK(polyline->vertlist.size() == 4u);
}

const std::vector<WritableTypeEntry> &writableTypeRegistry() {
  static const std::vector<WritableTypeEntry> entries = {
      {"POINT", writeRegistryPoint, 1, registryPointCount, assertRegistryPoint},
      {"LINE", writeRegistryLine, 1, registryLineCount, assertRegistryLine},
      {"CIRCLE", writeRegistryCircle, 1, registryCircleCount,
       assertRegistryCircle},
      {"ARC", writeRegistryArc, 1, registryArcCount, assertRegistryArc},
      {"ELLIPSE", writeRegistryEllipse, 1, registryEllipseCount,
       assertRegistryEllipse},
      {"MPOLYGON", writeRegistryMPolygon, 1, registryMPolygonCount,
       assertRegistryMPolygon},
  };
  return entries;
}

class ArcDimensionRoundTripIface : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  std::vector<DRW_DimArc> m_arcDimensions;

  void writeEntities() override {
    if (m_writer == nullptr)
      return;

    DRW_DimArc dim;
    dim.setArcDefPoint(DRW_Coord{5.0, 6.0, 0.0});
    dim.setExtLine1(DRW_Coord{1.0, 0.0, 0.0});
    dim.setExtLine2(DRW_Coord{0.0, 1.0, 0.0});
    dim.setArcCenter(DRW_Coord{0.0, 0.0, 0.0});
    dim.setLeaderPt1(DRW_Coord{2.0, 2.0, 0.0});
    dim.leaderPt2 = DRW_Coord{3.0, 3.0, 0.0};
    dim.arcStartAngle = 0.25;
    dim.arcEndAngle = 1.25;
    dim.isPartial = true;
    dim.hasLeader = true;
    dim.color = 2;
    m_writer->writeDimension(&dim);
  }

  void addDimArc(const DRW_DimArc *dim) override {
    if (dim != nullptr)
      m_arcDimensions.push_back(*dim);
  }
};

void putRawObjectPreamble(dwgBufferW &body, DRW::Version version,
                          std::uint16_t oType, std::uint32_t handle);
void putRawCommonObjectHandles(dwgBufferW &body, std::uint32_t parentHandle);
dwgHandle rawObjectHandle(std::uint8_t code, std::uint32_t ref);

DRW_UnsupportedObject makeRawReplayObject(DRW::Version version,
                                          std::uint16_t rawClassNumber) {
  dwgBufferW body;
  dwgBufferW handles;
  putRawObjectPreamble(body, version, rawClassNumber, 0x700u);
  if (version > DRW::AC1024)
    body.putBit(1);               // has_ds_data
  body.putRawLong32(0x12345678u); // opaque class-specific payload
  body.putRawShort16(0xabcd);
  body.putRawChar8(0x5au);
  if (version > DRW::AC1018) {
    // R2007+ object data ends with the string-stream footer even when no
    // detached strings are present.  There is no separate handle stream
    // in this synthetic payload, so its frame handle-bit count is zero.
    body.alignToByte();
    for (int i = 0; i < 7; ++i)
      body.putBit(0);
    body.putRawShort16(0);
    body.putBit(0);
    body.alignToByte();
    handles.putHandle(rawObjectHandle(4, 0)); // owner
    handles.putHandle(rawObjectHandle(0, 0)); // xdictionary
    handles.alignToByte();
  } else {
    putRawCommonObjectHandles(body, 0);
  }
  if (version > DRW::AC1014 && version < DRW::AC1024) {
    const std::uint8_t bsCode = (body.data()[0] >> 6) & 0x03;
    const std::size_t rlBitOffset = (bsCode == 0x01)   ? 10
                                    : (bsCode == 0x00) ? 18
                                                       : 2;
    body.patchRawLong32AtBit(rlBitOffset,
                             static_cast<std::uint32_t>(body.bitCount()));
  }

  DRW_UnsupportedObject object;
  object.m_version = version;
  object.m_objectType = rawClassNumber;
  object.m_handle = 0x700;
  std::vector<std::uint8_t> rawBytes = body.data();
  rawBytes.insert(rawBytes.end(), handles.data().begin(), handles.data().end());
  object.m_bodyBitSize = version > DRW::AC1021
                             ? static_cast<std::uint32_t>(handles.size() * 8u)
                             : 0u;
  object.m_objectSize = static_cast<std::uint32_t>(rawBytes.size());
  object.m_isEntity = false;
  object.m_isCustomClass = true;
  object.m_recordName = "RAW_REPLAY_TEST";
  object.m_className = "AcDbRawReplayTest";
  object.m_hasDataStorage = version > DRW::AC1024;
  object.m_rawBytes = std::move(rawBytes);
  return object;
}

DRW_UnsupportedObject makeRawWideHandleReplayObject(DRW::Version version) {
  constexpr std::uint16_t rawClassNumber = 509;
  constexpr std::uint32_t objectHandle = 0x701u;
  constexpr std::uint64_t payloadHandle = 0x0102030405ULL;

  dwgBufferW body;
  dwgBufferW handles;
  putRawObjectPreamble(body, version, rawClassNumber, objectHandle);
  if (version > DRW::AC1024)
    body.putBit(1); // has_ds_data
  dwgHandle wideHandle;
  wideHandle.code = 4;
  wideHandle.size = 5;
  wideHandle.ref = static_cast<std::uint32_t>(payloadHandle);
  wideHandle.ref64 = payloadHandle;
  body.putHandle(wideHandle);
  body.putRawLong32(0x12345678u);
  if (version > DRW::AC1018) {
    body.alignToByte();
    for (int i = 0; i < 7; ++i)
      body.putBit(0);
    body.putRawShort16(0);
    body.putBit(0);
    body.alignToByte();
    handles.putHandle(rawObjectHandle(4, 0)); // owner
    handles.putHandle(rawObjectHandle(0, 0)); // xdictionary
    handles.alignToByte();
  } else {
    putRawCommonObjectHandles(body, 0);
  }
  if (version > DRW::AC1014 && version < DRW::AC1024) {
    const std::uint8_t bsCode = (body.data()[0] >> 6) & 0x03;
    const std::size_t rlBitOffset = (bsCode == 0x01)   ? 10
                                    : (bsCode == 0x00) ? 18
                                                       : 2;
    body.patchRawLong32AtBit(rlBitOffset,
                             static_cast<std::uint32_t>(body.bitCount()));
  }

  DRW_UnsupportedObject object;
  object.m_version = version;
  object.m_objectType = rawClassNumber;
  object.m_handle = objectHandle;
  std::vector<std::uint8_t> rawBytes = body.data();
  rawBytes.insert(rawBytes.end(), handles.data().begin(), handles.data().end());
  object.m_bodyBitSize = version > DRW::AC1021
                             ? static_cast<std::uint32_t>(handles.size() * 8u)
                             : 0u;
  object.m_objectSize = static_cast<std::uint32_t>(rawBytes.size());
  object.m_isEntity = false;
  object.m_isCustomClass = true;
  object.m_recordName = "RAW_WIDE_HANDLE_TEST";
  object.m_className = "AcDbRawWideHandleTest";
  object.m_hasDataStorage = version > DRW::AC1024;
  object.m_rawBytes = std::move(rawBytes);
  return object;
}

DRW_UnsupportedObject makeRawFixedPlaceholderObject(DRW::Version version,
                                                    std::uint16_t objectType,
                                                    const char *recordName,
                                                    std::uint32_t handle) {
  dwgBufferW body;
  putRawObjectPreamble(body, version, objectType, handle);
  if (version > DRW::AC1024)
    body.putBit(0); // has_ds_data
  putRawCommonObjectHandles(body, 0);
  body.putRawChar8(static_cast<std::uint8_t>(objectType));
  if (version > DRW::AC1018) {
    body.alignToByte();
    for (int i = 0; i < 7; ++i)
      body.putBit(0);
    body.putRawShort16(0);
    body.putBit(0);
    body.alignToByte();
  }
  if (version > DRW::AC1014 && version < DRW::AC1024) {
    const std::uint8_t bsCode = (body.data()[0] >> 6) & 0x03;
    const std::size_t rlBitOffset = (bsCode == 0x01)   ? 10
                                    : (bsCode == 0x00) ? 18
                                                       : 2;
    body.patchRawLong32AtBit(rlBitOffset,
                             static_cast<std::uint32_t>(body.bitCount()));
  }

  DRW_UnsupportedObject object;
  object.m_version = version;
  object.m_objectType = objectType;
  object.m_handle = handle;
  object.m_bodyBitSize = 0;
  object.m_objectSize = static_cast<std::uint32_t>(body.data().size());
  object.m_isEntity = false;
  object.m_isCustomClass = false;
  object.m_recordName = recordName;
  object.m_rawBytes = body.data();
  return object;
}

DRW_UnsupportedObject makeRawVbaProjectObject(DRW::Version version) {
  constexpr std::uint32_t handle = 0x717u;
  constexpr std::uint32_t parentHandle = 0xA11u;
  const std::vector<std::uint8_t> payload{0x56u, 0x42u, 0x41u, 0x01u};

  dwgBufferW body;
  putRawObjectPreamble(body, version, DRW_VbaProject::kDwgType, handle);
  if (version > DRW::AC1024)
    body.putBit(0); // has_ds_data
  body.putBitLong(static_cast<std::int32_t>(payload.size()));
  body.putBytes(payload.data(), payload.size());

  dwgBufferW handles;
  if (version > DRW::AC1018) {
    body.putBit(0); // no detached strings
    body.putRawShort16(0);
    body.putBit(0);
    body.alignToByte();
    handles.putHandle(rawObjectHandle(4, parentHandle));
    handles.putHandle(rawObjectHandle(0, 0));
    handles.alignToByte();
  } else {
    const std::uint8_t bsCode = (body.data()[0] >> 6) & 0x03;
    const std::size_t rlBitOffset = (bsCode == 0x01)   ? 10
                                    : (bsCode == 0x00) ? 18
                                                       : 2;
    body.patchRawLong32AtBit(rlBitOffset,
                             static_cast<std::uint32_t>(body.bitCount()));
    putRawCommonObjectHandles(body, parentHandle);
  }

  std::vector<std::uint8_t> rawBytes = body.data();
  rawBytes.insert(rawBytes.end(), handles.data().begin(), handles.data().end());

  if (version > DRW::AC1018 && version < DRW::AC1024) {
    const std::uint8_t bsCode = (rawBytes[0] >> 6) & 0x03;
    const std::size_t rlBitOffset = (bsCode == 0x01)   ? 10
                                    : (bsCode == 0x00) ? 18
                                                       : 2;
    dwgBufferW patched;
    patched.putBytes(rawBytes.data(), rawBytes.size());
    patched.patchRawLong32AtBit(rlBitOffset,
                                static_cast<std::uint32_t>(body.bitCount()));
    rawBytes = patched.data();
  }

  DRW_UnsupportedObject object;
  object.m_version = version;
  object.m_objectType = DRW_VbaProject::kDwgType;
  object.m_handle = handle;
  object.m_bodyBitSize = version > DRW::AC1021
                             ? static_cast<std::uint32_t>(handles.size() * 8u)
                             : 0u;
  object.m_objectSize = static_cast<std::uint32_t>(rawBytes.size());
  object.m_isEntity = false;
  object.m_isCustomClass = false;
  object.m_recordName = "VBA_PROJECT";
  object.m_className = "AcDbVbaProject";
  object.m_rawBytes = std::move(rawBytes);
  return object;
}

std::uint32_t putProxyObjectPreamble(dwgBufferW &body, DRW::Version version,
                                     std::uint16_t objectType,
                                     std::uint32_t handle) {
  body.putObjType(version, objectType);
  std::uint32_t objectSizeBit = 0;
  if (version > DRW::AC1014 && version < DRW::AC1024) {
    objectSizeBit = body.bitCount();
    body.putRawLong32(0);
  }
  dwgHandle objectHandle;
  objectHandle.code = 4;
  objectHandle.ref = handle;
  body.putHandle(objectHandle);
  body.putBitShort(0); // EED size
  body.putBitLong(0);  // numReactors
  if (version > DRW::AC1015)
    body.putBit(0); // xDictFlag: xdictionary handle follows
  return objectSizeBit;
}

DRW_UnsupportedObject makeRawProxyObject(DRW::Version version,
                                         bool truncated = false,
                                         bool truncatedObjectId = false) {
  constexpr std::uint32_t handle = 0x720u;
  constexpr std::uint32_t parentHandle = 0x123u;
  constexpr std::uint32_t referencedHandle = 0x735u;
  dwgBufferW body;
  const std::uint32_t objectSizeBit =
      putProxyObjectPreamble(body, version, DRW_ProxyObject::kDwgType, handle);
  if (version > DRW::AC1024)
    body.putBit(0); // has_ds_data

  if (truncated) {
    body.put2Bits(0); // full BL follows, but the declared body ends here
  } else {
    body.putBitLong(500); // proxy carrier/class id
    if (version == DRW::AC1018)
      body.putVariableText(version, "AcDbProxyObject");
    if (version >= DRW::AC1032) {
      body.putBitLong(0x1234); // DWG version
      body.putBitLong(0x0002); // maintenance version
    } else {
      body.putBitLong(static_cast<std::int32_t>(0x00021234));
    }
    body.putBit(1);         // source was DXF
    body.putRawChar8(0xA5); // opaque proxy payload
    body.putRawChar8(0x5A);
    if (version > DRW::AC1018)
      body.putBit(0); // string stream: no subclass text
  }

  const std::uint32_t dataEndBit = body.bitCount();
  if (objectSizeBit != 0)
    body.patchRawLong32AtBit(objectSizeBit, dataEndBit);
  putRawCommonObjectHandles(body, parentHandle);
  dwgHandle referenced;
  referenced.code = 5;
  referenced.ref = referencedHandle;
  body.putHandle(referenced);
  if (truncatedObjectId)
    body.putRawChar8(0x5F); // code 5, payload length 15, no payload
  dwgHandle nullHandle;
  body.putHandle(nullHandle);

  DRW_UnsupportedObject object;
  object.m_version = version;
  object.m_objectType = DRW_ProxyObject::kDwgType;
  object.m_handle = handle;
  object.m_bodyBitSize =
      version > DRW::AC1021
          ? static_cast<std::uint32_t>(body.data().size() * 8u - dataEndBit)
          : 0;
  object.m_objectSize = static_cast<std::uint32_t>(body.data().size());
  object.m_isEntity = false;
  object.m_isCustomClass = false;
  object.m_recordName = "ACAD_PROXY_OBJECT";
  object.m_className = "AcDbProxyObject";
  object.m_rawBytes = body.data();
  return object;
}

dwgHandle rawObjectHandle(std::uint8_t code, std::uint32_t ref) {
  dwgHandle h;
  h.code = (ref == 0) ? 0 : code;
  h.size = 0;
  h.ref = ref;
  return h;
}

void putRawObjectPreamble(dwgBufferW &body, DRW::Version version,
                          std::uint16_t oType, std::uint32_t handle) {
  body.putObjType(version, oType);
  if (version > DRW::AC1014 && version < DRW::AC1024)
    body.putRawLong32(0); // object-size-in-bits placeholder
  body.putHandle(rawObjectHandle(4, handle));
  body.putBitShort(0); // EED size
  body.putBitLong(0);  // numReactors
  if (version > DRW::AC1015)
    body.putBit(0); // xDictFlag: xdictionary handle follows
}

void putRawEntityPreamble(dwgBufferW &body, DRW::Version version,
                          std::uint16_t oType, std::uint32_t handle) {
  body.putObjType(version, oType);
  if (version > DRW::AC1014 && version < DRW::AC1024)
    body.putRawLong32(0); // object-size-in-bits placeholder
  body.putHandle(rawObjectHandle(0, handle));
  body.putBitShort(0); // EED size
  body.putBit(0);      // graphFlag: no graphics data
  body.put2Bits(2);    // entmode: modelspace, no owner handle
  body.putBitLong(0);  // numReactors
  if (version == DRW::AC1015) {
    body.putBit(1); // no prev/next entity links
  } else {
    body.putBit(0); // xDictFlag: xdictionary handle follows
    if (version > DRW::AC1024)
      body.putBit(0); // hasDsData
  }
  body.putEnColor(version, 256);
  body.putBitDouble(1.0); // ltype scale
  body.put2Bits(0);       // linetype BYLAYER
  body.put2Bits(0);       // plot style BYLAYER
  if (version > DRW::AC1018) {
    body.put2Bits(0);    // material BYLAYER
    body.putRawChar8(0); // shadow inherited
  }
  if (version > DRW::AC1021) {
    body.putBit(0); // no full visual style
    body.putBit(0); // no face visual style
    body.putBit(0); // no edge visual style
  }
  body.putBitShort(0);  // visible
  body.putRawChar8(29); // lineweight BYLAYER
}

void putRawCommonObjectHandles(dwgBufferW &body, std::uint32_t parentHandle) {
  body.putHandle(rawObjectHandle(4, parentHandle));
  body.putHandle(rawObjectHandle(0, 0)); // xdictionary
}

void putRawCommonEntityHandles(dwgBufferW &body, std::uint32_t layerHandle) {
  body.putHandle(rawObjectHandle(0, 0)); // xdictionary
  body.putHandle(rawObjectHandle(5, layerHandle));
}

DRW_UnsupportedObject makeRawViewportEntityHeaderControl(DRW::Version version) {
  constexpr std::uint16_t objectType =
      DRW_ViewportEntityHeader::kDwgControlType;
  constexpr std::uint32_t handle = DRW_ViewportEntityHeader::kDwgControlHandle;
  dwgBufferW body;
  putRawObjectPreamble(body, version, objectType, handle);
  body.putBitLong(0);                    // no VP_ENT_HDR children
  body.putHandle(rawObjectHandle(0, 0)); // null handle
  body.putHandle(rawObjectHandle(0, 0)); // xdictionary

  DRW_UnsupportedObject object;
  object.m_version = version;
  object.m_objectType = objectType;
  object.m_handle = handle;
  object.m_bodyBitSize = version > DRW::AC1021 ? body.bitCount() : 0;
  object.m_objectSize = static_cast<std::uint32_t>(body.data().size());
  object.m_isEntity = false;
  object.m_isCustomClass = false;
  object.m_rawBytes = body.data();
  return object;
}

