class MLeaderBlockRetryIface final : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  bool m_firstAttemptFailed{false};
  bool m_retrySucceeded{false};

  void writeBlocks() override {
    REQUIRE(m_writer != nullptr);
    m_blockRecordHandle =
        m_writer->defineBlock("MLeaderBlockOwnedRetry", DRW_Coord{});
    REQUIRE(m_blockRecordHandle != 0u);
    REQUIRE(m_writer->beginBlockContent(m_blockRecordHandle));
  }

  void writeEntities() override {
    REQUIRE(m_writer != nullptr);
    const std::uint64_t failedTransaction = m_writer->beginDwgWriteTransaction(
        /*suppressFailureCounters=*/true,
        /*trackCallerMutations=*/true,
        /*includeAdmissionState=*/false);
    REQUIRE(failedTransaction != 0u);

    DRW_MLeader rejected = makeLeader("discarded MLeader", 0.0);
    DwgCompoundWriteTestAccess::failAfterFirstBlockOwnedEntity(*m_writer);
    m_firstAttemptFailed = !m_writer->writeMLeader(&rejected);
    CHECK(m_firstAttemptFailed);
    REQUIRE(m_writer->rollbackDwgWriteTransaction(failedTransaction));
    CHECK(rejected.handle == 0u);

    const std::uint64_t retryTransaction = m_writer->beginDwgWriteTransaction(
        /*suppressFailureCounters=*/true,
        /*trackCallerMutations=*/true,
        /*includeAdmissionState=*/false);
    REQUIRE(retryTransaction != 0u);
    DRW_MLeader first = makeLeader("first retried MLeader", 10.0);
    DRW_MLeader second = makeLeader("second retried MLeader", 20.0);
    m_retrySucceeded =
        m_writer->writeMLeader(&first) && m_writer->writeMLeader(&second);
    REQUIRE(m_retrySucceeded);
    REQUIRE(m_writer->commitDwgWriteTransaction(retryTransaction));
    REQUIRE(m_writer->endBlockContent());
  }

private:
  static DRW_MLeader makeLeader(const char *text, double offset) {
    DRW_MLeader leader;
    leader.classVersion = 2;
    leader.leaderType = 1;
    leader.leaderColor = 7;
    leader.styleContentType = 2;
    leader.scaleFactor = 1.0;

    DRW_MLeaderRoot root;
    root.isContentValid = true;
    root.connectionPoint = DRW_Coord{offset + 10.0, 5.0, 0.0};
    root.direction = DRW_Coord{1.0, 0.0, 0.0};
    DRW_MLeaderLeaderLine line;
    line.points = {DRW_Coord{offset, 0.0, 0.0},
                   DRW_Coord{offset + 10.0, 5.0, 0.0}};
    root.leaderLines.push_back(std::move(line));
    leader.context.roots.push_back(std::move(root));

    leader.context.overallScale = 1.0;
    leader.context.contentBasePoint = DRW_Coord{offset + 10.0, 5.0, 0.0};
    leader.context.hasTextContents = true;
    leader.context.textLabel = text;
    leader.context.textNormal = DRW_Coord{0.0, 0.0, 1.0};
    leader.context.textLocation = DRW_Coord{offset + 10.0, 5.0, 0.0};
    leader.context.textDirection = DRW_Coord{1.0, 0.0, 0.0};
    leader.context.basePoint = leader.context.textLocation;
    leader.context.baseDirection = DRW_Coord{1.0, 0.0, 0.0};
    leader.context.baseVertical = DRW_Coord{0.0, 1.0, 0.0};
    return leader;
  }

  std::uint32_t m_blockRecordHandle{0};
};

