class MLineSidecarSourceIface final : public EmptyIface {
public:
  dwgRW *writer{nullptr};

  static constexpr std::uint32_t kStyleHandle = 0xB40u;

  void writeObjects() override {
    REQUIRE(writer != nullptr);
    DRW_MLineStyle style;
    style.handle = kStyleHandle;
    style.parentHandle = DRW::DwgNamedObjectsDictionaryHandle;
    style.name = "MLINE-SIDECAR-STYLE";
    style.description = "MLINE sidecar style linkage";
    DRW_MLineElement first;
    first.offset = -0.5;
    DRW_MLineElement second;
    second.offset = 0.5;
    style.elements = {first, second};
    REQUIRE(writer->writeMLineStyle(&style));
  }

  void writeEntities() override {
    REQUIRE(writer != nullptr);
    DRW_MLine mline;
    mline.layer = "0";
    mline.styleName = "MLINE-SIDECAR-STYLE";
    mline.styleHandle = kStyleHandle;
    mline.scale = 2.0;
    mline.justification = 1;
    mline.openClosed = 0;
    mline.numLines = 2;
    mline.numVerts = 2;
    mline.basePoint = DRW_Coord{0.0, 0.0, 0.0};
    for (int i = 0; i < 2; ++i) {
      DRW_MLineVertex vertex;
      vertex.position = DRW_Coord{10.0 * i, 0.0, 0.0};
      vertex.vertexDir = DRW_Coord{1.0, 0.0, 0.0};
      vertex.miterDir = DRW_Coord{0.0, 1.0, 0.0};
      vertex.segParms.assign(2, std::vector<double>{0.0});
      vertex.areaFillParms.assign(2, std::vector<double>{});
      mline.vertlist.push_back(std::move(vertex));
    }
    REQUIRE(writer->writeMLine(&mline));
  }
};

