class LightListRoundTripIface : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  DRW_LightList m_lightList;
  std::vector<DRW_Light> m_writtenLights;
  std::vector<DRW_LightList> m_lightLists;
  std::vector<DRW_UnsupportedObject> m_rawObjects;

  LightListRoundTripIface() {
    m_lightList.handle = 0x841u;
    m_lightList.parentHandle = 0x0Cu;
    m_lightList.reactorHandles = {0x845u};
    m_lightList.xDictHandle = 0x846u;
    m_lightList.setDwgCommonObjectState(1, 0, false);
    m_lightList.m_classVersion = 1u;
    m_lightList.m_lights = {{0x41u, "Key"}, {0x42u, "Fill"}};
    m_lightList.m_lightCount =
        static_cast<std::uint32_t>(m_lightList.m_lights.size());
    REQUIRE(m_lightList.addExtData(
        std::make_unique<DRW_Variant>(1001, "LIGHTLIST_EED")));
    REQUIRE(m_lightList.addExtData(
        std::make_unique<DRW_Variant>(1000, "lightlist payload")));
  }

  void collectDwgAppIds() override {
    if (m_writer == nullptr)
      return;
    DRW_AppId appId;
    appId.name = "LIGHTLIST_EED";
    REQUIRE(m_writer->addAppId(&appId));
  }

  void writeDwgClasses() override {
    if (m_writer != nullptr)
      REQUIRE(m_writer->registerLightListObjectClass(&m_lightList));
  }

  void writeObjects() override {
    if (m_writer != nullptr)
      REQUIRE(m_writer->writeLightList(&m_lightList));
  }

  void writeEntities() override {
    if (m_writer == nullptr || m_writer->getVersion() < DRW::AC1021)
      return;

    for (const auto &entry : m_lightList.m_lights) {
      DRW_Light light;
      light.handle = entry.m_handle;
      light.m_name = entry.m_name;
      light.m_classVersion = 1;
      light.m_type = 1;
      light.m_status = true;
      light.m_intensity = 1.0;
      REQUIRE(m_writer->writeLight(&light));
      m_writtenLights.push_back(light);
    }
  }

  void addLight(const DRW_Light &light) override {
    m_writtenLights.push_back(light);
  }

  void addLightList(const DRW_LightList &lightList) override {
    m_lightLists.push_back(lightList);
  }

  void addUnsupportedObject(const DRW_UnsupportedObject &object) override {
    m_rawObjects.push_back(object);
  }
};

