class HatchGradientRoundTripIface : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  std::vector<DRW_Hatch> m_hatches;

  void writeEntities() override {
    if (m_writer == nullptr)
      return;

    DRW_Hatch hatch;
    hatch.color = 5;
    hatch.solid = 0;
    hatch.name = "DASHED";
    hatch.extPoint = DRW_Coord{0.0, 0.0, 1.0};
    hatch.angle = 0.25;
    hatch.scale = 2.5;
    hatch.doubleflag = 1;
    DRW_Hatch::PatternLine patternLine;
    patternLine.angle = 0.5;
    patternLine.baseX = 1.0;
    patternLine.baseY = 2.0;
    patternLine.offsetX = 3.0;
    patternLine.offsetY = 4.0;
    patternLine.dashList = {5.0, -2.0};
    hatch.patternLines.push_back(patternLine);
    hatch.isGradient = 1;
    hatch.gradReserved = 0;
    hatch.gradAngle = 0.75;
    hatch.gradShift = 0.25;
    hatch.singleColor = 0;
    hatch.gradTint = 0.5;
    hatch.gradName = "LINEAR";
    DRW_Hatch::GradientStop first;
    first.value = 0.0;
    first.rgb = 0x00ff0000;
    first.aciColor = 1;
    hatch.gradColors.push_back(first);
    DRW_Hatch::GradientStop second;
    second.value = 1.0;
    second.rgb = 0x000000ff;
    second.aciColor = 5;
    hatch.gradColors.push_back(second);
    REQUIRE(m_writer->writeHatch(&hatch));
  }

  void addHatch(const DRW_Hatch *hatch) override {
    if (hatch != nullptr)
      m_hatches.push_back(*hatch);
  }
};

class MultilineAttributeWriteIface : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  std::uint32_t m_blockRecH{0};
  std::vector<DRW_Attdef> m_attdefs;
  std::vector<DRW_Insert> m_inserts;

  static std::unique_ptr<DRW_MText> makeMText(const char *value) {
    auto mtext = std::make_unique<DRW_MText>();
    mtext->basePoint = DRW_Coord{1.0, 2.0, 0.0};
    mtext->extPoint = DRW_Coord{0.0, 0.0, 1.0};
    mtext->secPoint = DRW_Coord{1.0, 0.0, 0.0};
    mtext->widthscale = 20.0;
    mtext->height = 2.5;
    mtext->textgen = 1;
    mtext->alignH = DRW_Text::HLeft;
    mtext->interlin = 1.0;
    mtext->text = value;
    mtext->m_r2018IsNotAnnotative = true;
    mtext->m_r2018ReallyLocked = true;
    mtext->m_r2018AppIdHandle = 0x14u;
    mtext->m_r2018AnnotativeData = {0x01, 0x7F, 0xFE};
    mtext->m_r2018AnnotativeUnknown = 0x72;
    mtext->m_r2018AnnotativeAppHandle = 0x24u;
    mtext->reactorHandles = {0x31u, 0x32u};
    mtext->xDictHandle = 0x33u;
    mtext->setHasDataStorageBinaryData(true);
    // Named AcDbColor ENC records use the high byte for flags.  Use the
    // valid ByLayer index here; an indexed value with bit 8 set would
    // alias the name/handle flags in the 16-bit wire field.
    mtext->color = 256;
    mtext->colorName = "Book$Entry";
    mtext->transparency = 0x03000080;
    mtext->setDwgAcDbColorHandle(true, 0x35u);
    mtext->ltypeScale = 1.25;
    mtext->lineType.clear();
    mtext->visible = false;
    mtext->lWeight = DRW_LW_Conv::width05;
    mtext->material = 0x36u;
    mtext->shadow = DRW::IgnoreShadows;
    mtext->shadowHandle = 0x37u;
    mtext->plotStyle = 0x38u;
    mtext->fullVisualStyleHandle = 0x39u;
    mtext->faceVisualStyleHandle = 0x3Au;
    mtext->edgeVisualStyleHandle = 0x3Bu;
    mtext->setDwgLayerHandle(0x3Cu);
    mtext->setDwgLinetypeHandle(0x3Du);
    return mtext;
  }

  void writeBlocks() override {
    if (m_writer == nullptr)
      return;

    m_blockRecH = m_writer->defineBlock("MultilineAttributeBlock",
                                        DRW_Coord{0.0, 0.0, 0.0});
    REQUIRE(m_blockRecH != 0);
    REQUIRE(m_writer->beginBlockContent(m_blockRecH));

    DRW_Attdef attdef;
    attdef.basePoint = DRW_Coord{8.0, 9.0, 0.0};
    attdef.secPoint = attdef.basePoint;
    attdef.extPoint = DRW_Coord{0.0, 0.0, 1.0};
    attdef.height = 2.5;
    attdef.widthscale = 1.0;
    attdef.text = "default";
    attdef.tag = "ML_ATTDEF";
    attdef.prompt = "Prompt";
    attdef.attVersion = 1;
    attdef.m_attributeType = 4;
    attdef.keepDuplicateRecords = 0x5A;
    attdef.mtext = makeMText("default\\Pvalue");
    REQUIRE(m_writer->writeAttdef(&attdef));
    REQUIRE(m_writer->endBlockContent());
  }

  void writeEntities() override {
    if (m_writer == nullptr || m_blockRecH == 0)
      return;

    DRW_Insert insert;
    insert.basePoint = DRW_Coord{4.0, 5.0, 0.0};
    insert.extPoint = DRW_Coord{0.0, 0.0, 1.0};
    insert.blockRecH.ref = m_blockRecH;

    auto attrib = std::make_shared<DRW_Attrib>();
    attrib->basePoint = insert.basePoint;
    attrib->secPoint = attrib->basePoint;
    attrib->extPoint = DRW_Coord{0.0, 0.0, 1.0};
    attrib->height = 2.5;
    attrib->widthscale = 1.0;
    attrib->text = "line 1";
    attrib->tag = "ML_ATTRIB";
    attrib->attVersion = 1;
    attrib->m_attributeType = 2;
    attrib->keepDuplicateRecords = 0xA5;
    attrib->mtext = makeMText("line 1\\Pline 2");
    insert.attlist.push_back(std::move(attrib));
    REQUIRE(m_writer->writeInsert(&insert));
  }

  void addAttDef(const DRW_Attdef &attdef) override {
    m_attdefs.push_back(attdef);
  }

  void addInsert(const DRW_Insert &insert) override {
    m_inserts.push_back(insert);
  }
};

