class PlotSettingsRoundTripIface : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  DRW_PlotSettings m_settings;
  DRW_PlotSettings m_secondSettings;
  std::vector<DRW_PlotSettings> m_plotSettings;
  bool m_writeSecondSettings{false};

  PlotSettingsRoundTripIface() {
    m_settings.handle = 0x7B1u;
    m_settings.parentHandle = DRW::DwgNamedObjectsDictionaryHandle;
    m_settings.reactorHandles = {0x7B3u};
    m_settings.xDictHandle = 0x7B4u;
    m_settings.setDwgCommonObjectState(1, 0, false);
    m_settings.pageSetupName = "PLOTSETTINGS_PAGE";
    m_settings.printerConfig = "PLOTSETTINGS_PRINTER";
    m_settings.paperSize = "ISO_A3";
    m_settings.currentStyleSheet = "acad.ctb";
    m_settings.plotLayoutFlags = 688;
    m_settings.marginLeft = 7.0;
    m_settings.marginTop = 8.0;
    m_settings.paperWidth = 420.0;
    m_settings.paperHeight = 297.0;
    m_settings.plotType = 3;
    m_settings.scaleType = 4;
    REQUIRE(m_settings.addExtData(
        std::make_unique<DRW_Variant>(1001, "PLOTSETTINGS_EED")));
    REQUIRE(m_settings.addExtData(
        std::make_unique<DRW_Variant>(1000, "plot settings payload")));
    m_secondSettings = m_settings;
    m_secondSettings.handle = 0x7B2u;
    m_secondSettings.printerConfig = "PLOTSETTINGS_SECOND_PRINTER";
    m_secondSettings.extData.clear();
    REQUIRE(m_secondSettings.addExtData(
        std::make_unique<DRW_Variant>(1001, "PLOTSETTINGS_SECOND_EED")));
    REQUIRE(m_secondSettings.addExtData(
        std::make_unique<DRW_Variant>(1000, "second plot settings payload")));
  }

  void writeDwgClasses() override {
    if (m_writer != nullptr) {
      REQUIRE(m_writer->registerPlotSettingsObjectClass(m_settings.handle));
      if (m_writeSecondSettings)
        REQUIRE(
            m_writer->registerPlotSettingsObjectClass(m_secondSettings.handle));
    }
  }

  void collectDwgAppIds() override {
    if (m_writer == nullptr)
      return;
    const auto collect = [this](const DRW_PlotSettings &settings) {
      for (const auto &value : settings.extData) {
        if (value == nullptr || value->code() != 1001)
          continue;
        DRW_AppId appId;
        appId.name = value->c_str();
        REQUIRE(m_writer->addAppId(&appId));
      }
    };
    collect(m_settings);
    if (m_writeSecondSettings)
      collect(m_secondSettings);
  }

  void writeObjects() override {
    if (m_writer != nullptr) {
      REQUIRE(m_writer->writePlotSettings(&m_settings));
      if (m_writeSecondSettings)
        REQUIRE(m_writer->writePlotSettings(&m_secondSettings));
    }
  }

  void addPlotSettings(const DRW_PlotSettings *settings) override {
    if (settings != nullptr)
      m_plotSettings.push_back(*settings);
  }
};

// DICTIONARY round-trip — populates a tiny named-object dictionary with
// two entries, writes it via the native encoder, then reads back and
// asserts every field survived.  Exercises PR 8b's writeDictionary path
// plus the existing DRW_Dictionary::encodeDwg / parseDwg pair.
class DictionaryRoundTripIface : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  DRW_Dictionary m_dictionary;
  std::vector<DRW_Dictionary> m_dictionaries;
  std::vector<DRW_UnsupportedObject> m_rawObjects;
  std::vector<DRW_DwgFramePublication> m_framePublications;
  bool m_registerEedAppId{true};
  bool m_dictionaryWritten{false};

  DictionaryRoundTripIface() {
    m_dictionary.handle = 0x7A0u;
    m_dictionary.parentHandle = 0xCu;
    m_dictionary.reactorHandles = {0x7A3u};
    m_dictionary.xDictHandle = 0x7A4u;
    m_dictionary.setDwgCommonObjectState(1, 0, false);
    m_dictionary.cloning = 1; // KeepExisting
    m_dictionary.hardOwner = 0;
    DRW_Dictionary::Entry e1;
    e1.m_name = "ACAD_PLOTSETTINGS";
    e1.m_handle = 0x7A1u;
    m_dictionary.m_entries.push_back(e1);
    DRW_Dictionary::Entry e2;
    e2.m_name = "ACAD_GROUP";
    e2.m_handle = 0x7A2u;
    m_dictionary.m_entries.push_back(e2);
    REQUIRE(m_dictionary.addExtData(
        std::make_unique<DRW_Variant>(1001, "DICTIONARY_EED")));
    REQUIRE(m_dictionary.addExtData(
        std::make_unique<DRW_Variant>(1000, "dictionary payload")));
    REQUIRE(m_dictionary.addExtData(std::make_unique<DRW_Variant>(1070, 44)));
  }

  void collectDwgAppIds() override {
    if (m_writer == nullptr || !m_registerEedAppId)
      return;
    DRW_AppId appId;
    appId.name = "DICTIONARY_EED";
    REQUIRE(m_writer->addAppId(&appId));
  }

  void writeObjects() override {
    if (m_writer != nullptr)
      m_dictionaryWritten = m_writer->writeDictionary(&m_dictionary);
  }

  void addDictionary(const DRW_Dictionary &dictionary) override {
    m_dictionaries.push_back(dictionary);
  }

  void addUnsupportedObject(const DRW_UnsupportedObject &object) override {
    m_rawObjects.push_back(object);
  }

  void
  addDwgFramePublication(const DRW_DwgFramePublication &publication) override {
    m_framePublications.push_back(publication);
  }
};

class NamedObjectDictionaryIface final : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  DRW_Dictionary m_child;
  std::vector<DRW::DwgNamedObjectDictionaryEntry> m_receipt;
  std::vector<DRW_Dictionary> m_dictionaries;
  bool m_registered{false};
  bool m_childWritten{false};
  bool m_duplicateRegistration{false};
  bool m_lateRegistration{false};
  bool m_writeChild{true};

  NamedObjectDictionaryIface() {
    m_child.handle = 0xA90u;
    m_child.parentHandle = DRW::DwgNamedObjectsDictionaryHandle;
    m_child.cloning = 1;
  }

  void writeDwgClasses() override {
    REQUIRE(m_writer != nullptr);
    m_registered = m_writer->registerDwgNamedObjectDictionaryEntry(
        "ACAD_TABLESTYLE", m_child.handle);
    if (m_duplicateRegistration) {
      CHECK_FALSE(m_writer->registerDwgNamedObjectDictionaryEntry(
          "ACAD_TABLESTYLE", m_child.handle));
    }
  }

  void writeObjects() override {
    REQUIRE(m_writer != nullptr);
    if (m_lateRegistration) {
      CHECK_FALSE(m_writer->registerDwgNamedObjectDictionaryEntry("ACAD_LAYOUT",
                                                                  0xA91u));
    }
    if (m_writeChild)
      m_childWritten = m_writer->writeDictionary(&m_child);
  }

  bool finalizeDwgWrite() override {
    REQUIRE(m_writer != nullptr);
    return m_writer->getEmittedDwgNamedObjectDictionaryEntries(m_receipt);
  }

  void addDictionary(const DRW_Dictionary &dictionary) override {
    m_dictionaries.push_back(dictionary);
  }
};

// XRECORD round-trip — populates an extended-data record with a mix of
// primitive variant types (string, int, double) plus a handle-stream
// entry, then asserts post-round-trip equivalence.  Exercises PR 8b's
// writeXRecord path and the existing DRW_XRecord byte-counted data
// section encoder.
class XRecordRoundTripIface : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  DRW_XRecord m_xrecord;
  std::vector<DRW_XRecord> m_xrecords;
  bool m_registerEedAppId{true};
  bool m_xrecordWritten{false};

  XRecordRoundTripIface() {
    m_xrecord.handle = 0x7B0u;
    m_xrecord.parentHandle = 0xCu;
    m_xrecord.reactorHandles = {0x7B3u};
    m_xrecord.xDictHandle = 0x7B4u;
    m_xrecord.setDwgCommonObjectState(1, 0, false);
    m_xrecord.m_cloning = 1;
    m_xrecord.m_values.emplace_back(1, std::string("hello-xrecord"));
    m_xrecord.m_values.emplace_back(70, static_cast<std::int32_t>(42));
    m_xrecord.m_values.emplace_back(40, 3.14159);
    // Handle-stream entry — code 0 means it lives in the handle stream
    // (not the data block).  Parser reads via getOffsetHandle.
    m_xrecord.m_handleValues.emplace_back(0, 0x7B1u);
    REQUIRE(m_xrecord.addExtData(
        std::make_unique<DRW_Variant>(1001, "XRECORD_EED")));
    REQUIRE(m_xrecord.addExtData(
        std::make_unique<DRW_Variant>(1000, "xrecord payload")));
    REQUIRE(m_xrecord.addExtData(std::make_unique<DRW_Variant>(1070, 45)));
  }

  void collectDwgAppIds() override {
    if (m_writer == nullptr || !m_registerEedAppId)
      return;
    DRW_AppId appId;
    appId.name = "XRECORD_EED";
    REQUIRE(m_writer->addAppId(&appId));
  }

  void writeObjects() override {
    if (m_writer != nullptr)
      m_xrecordWritten = m_writer->writeXRecord(&m_xrecord);
  }

  void addXRecord(const DRW_XRecord &xrecord) override {
    m_xrecords.push_back(xrecord);
  }
};

