  DRW_Vport namedVport;
  namedVport.handle = 0xA53u;
  namedVport.name = "Missing VPORT refs";
  namedVport.backgroundHandle = 0xDEADu;
  namedVport.visualStyleHandle = 0xDEADu;
  namedVport.m_sunHandle = 0xDEADu;
  namedVport.namedUcsHandle = 0xDEADu;
  namedVport.baseUcsHandle = 0xDEADu;
  source.dwgAdvancedMetadata().addVport(namedVport);

  DRW_GeoData geoData;
  geoData.handle = 0xA54u;
  geoData.parentHandle = DRW::DwgNamedObjectsDictionaryHandle;
  geoData.m_hostBlockHandle = 0xDEADu;
  geoData.m_version = 3;
