class FieldClassAdmissionFailureFilter final : public RS_FilterDXFRW {
public:
  bool injected{false};

  void writeDwgClasses() override {
    if (dwgRW *writer = DwgWriteFailureTestAccess::activeWriter(*this)) {
      DwgWriteFailureTestAccess::failNextFieldClassRegistration(*writer);
      injected = true;
    }
    RS_FilterDXFRW::writeDwgClasses();
  }
};

