  rawEntity.m_objectType = 1200;
  rawEntity.m_handle = 0xA60u;
  rawEntity.m_isEntity = true;
  rawEntity.m_isCustomClass = true;
  rawEntity.m_recordName = "UNAVAILABLE_ENTITY";
  rawEntity.m_className = "AcDbUnavailableEntity";
  // The empty body makes this entity intentionally non-replayable. Its
  // handle must still not become a valid OBJECTS/dictionary target.
  source.dwgAdvancedMetadata().addUnsupportedObject(rawEntity);

