class TableEedRoundTripIface : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  std::vector<bool> m_results;
  std::vector<std::uint32_t> m_acceptedHandles;
  std::vector<std::size_t> m_readEedSizes;
  std::vector<std::string> m_readAppIds;
  std::vector<std::uint32_t> m_emittedTableHandles;
  std::vector<std::uint32_t> m_emittedTableControlHandles;
  std::vector<std::uint32_t> m_repeatedTableHandles;
  std::vector<std::uint32_t> m_repeatedTableControlHandles;
  bool m_tableCompletion{false};
  bool m_tableControlCompletion{false};
  bool m_repeatedCompletion{false};

  static void addEed(DRW_TableEntry &entry) {
    REQUIRE(entry.addExtData(std::make_unique<DRW_Variant>(1001, "XAPP")));
    REQUIRE(entry.addExtData(std::make_unique<DRW_Variant>(1000, "table EED")));
  }

  void writeLTypes() override {
    DRW_LType entry;
    entry.name = "EED_LTYPE";
    addEed(entry);
    m_results.push_back(m_writer->addLType(&entry));
    m_acceptedHandles.push_back(entry.handle);
  }

  void writeLayers() override {
    DRW_Layer entry;
    entry.name = "EED_LAYER";
    addEed(entry);
    m_results.push_back(m_writer->addLayer(&entry));
    m_acceptedHandles.push_back(entry.handle);
  }

  void writeTextstyles() override {
    DRW_Textstyle entry;
    entry.name = "EED_STYLE";
    addEed(entry);
    m_results.push_back(m_writer->addTextstyle(&entry));
    m_acceptedHandles.push_back(entry.handle);
  }

  void writeViews() override {
    DRW_View entry;
    entry.name = "EED_VIEW";
    addEed(entry);
    m_results.push_back(m_writer->addView(&entry));
    m_acceptedHandles.push_back(entry.handle);
  }

  void writeUCSs() override {
    DRW_UCS entry;
    entry.name = "EED_UCS";
    addEed(entry);
    m_results.push_back(m_writer->addUCS(&entry));
    m_acceptedHandles.push_back(entry.handle);
  }

  void writeVports() override {
    DRW_Vport entry;
    entry.name = "*Active";
    addEed(entry);
    m_results.push_back(m_writer->addVport(&entry));
    m_acceptedHandles.push_back(entry.handle);

    DRW_ViewportEntityHeader header;
    addEed(header);
    m_results.push_back(m_writer->addViewportEntityHeader(&header));
    m_acceptedHandles.push_back(header.handle);
  }

  void writeDimstyles() override {
    DRW_Dimstyle entry;
    entry.name = "STANDARD";
    addEed(entry);
    m_results.push_back(m_writer->addDimstyle(&entry));
    m_acceptedHandles.push_back(entry.handle);
  }

  void writeAppId() override {
    DRW_AppId entry;
    entry.name = "EED_APPID";
    addEed(entry);
    m_results.push_back(m_writer->addAppId(&entry));
    m_acceptedHandles.push_back(entry.handle);
  }

  void addLType(const DRW_LType &entry) override {
    if (entry.name == "EED_LTYPE")
      m_readEedSizes.push_back(entry.extData.size());
  }
  void addLayer(const DRW_Layer &entry) override {
    if (entry.name == "EED_LAYER")
      m_readEedSizes.push_back(entry.extData.size());
  }
  void addTextStyle(const DRW_Textstyle &entry) override {
    if (entry.name == "EED_STYLE")
      m_readEedSizes.push_back(entry.extData.size());
  }
  void addView(const DRW_View &entry) override {
    if (entry.name == "EED_VIEW")
      m_readEedSizes.push_back(entry.extData.size());
  }
  void addUCS(const DRW_UCS &entry) override {
    if (entry.name == "EED_UCS")
      m_readEedSizes.push_back(entry.extData.size());
  }
  void addVport(const DRW_Vport &entry) override {
    if (entry.name == "*ACTIVE")
      m_readEedSizes.push_back(entry.extData.size());
  }
  void addViewportEntityHeader(const DRW_ViewportEntityHeader &entry) override {
    m_readEedSizes.push_back(entry.extData.size());
  }
  void addDimStyle(const DRW_Dimstyle &entry) override {
    if (entry.name == "STANDARD")
      m_readEedSizes.push_back(entry.extData.size());
  }
  void addAppId(const DRW_AppId &entry) override {
    m_readAppIds.push_back(entry.name);
    if (entry.name == "EED_APPID")
      m_readEedSizes.push_back(entry.extData.size());
  }

  bool finalizeDwgWrite() override {
    if (m_writer == nullptr)
      return false;
    m_tableCompletion =
        m_writer->getEmittedDwgTableRecordHandles(m_emittedTableHandles);
    m_tableControlCompletion = m_writer->getEmittedDwgTableControlHandles(
        m_emittedTableControlHandles);
    const bool repeatedTableCompletion =
        m_writer->getEmittedDwgTableRecordHandles(m_repeatedTableHandles);
    const bool repeatedControlCompletion =
        m_writer->getEmittedDwgTableControlHandles(
            m_repeatedTableControlHandles);
    m_repeatedCompletion =
        repeatedTableCompletion && repeatedControlCompletion &&
        m_repeatedTableHandles == m_emittedTableHandles &&
        m_repeatedTableControlHandles == m_emittedTableControlHandles;
    return m_tableCompletion && m_tableControlCompletion &&
           m_repeatedCompletion;
  }
};

class PolylineRoundTripIface : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  std::vector<DRW_Polyline> m_polylines;
  std::vector<DRW_DwgFramePublication> m_framePublications;

  void writeEntities() override {
    if (m_writer == nullptr)
      return;
    DRW_Polyline pl;
    pl.flags = 1; // closed 2D polyline (bit 0)
    pl.addVertex(DRW_Vertex(0.0, 0.0, 0.0, 0.0));
    pl.addVertex(DRW_Vertex(10.0, 0.0, 0.0, 0.0));
    pl.addVertex(DRW_Vertex(10.0, 5.0, 0.0, 0.0));
    REQUIRE(m_writer->writePolyline(&pl));
  }
  void addPolyline(const DRW_Polyline &pl) override {
    m_polylines.push_back(pl);
  }
  void
  addDwgFramePublication(const DRW_DwgFramePublication &publication) override {
    m_framePublications.push_back(publication);
  }
};

class UserBlockCompoundRoundTripIface : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  std::map<std::string, std::vector<DRW_Polyline>> m_polylines;
  std::map<std::string, std::vector<DRW_Insert>> m_inserts;
  std::map<std::string, std::uint32_t> m_blockHandles;
  std::vector<DRW_DwgFramePublication> m_framePublications;

  void writeBlocks() override {
    if (m_writer == nullptr)
      return;

    REQUIRE(m_writer->defineBlock("CompoundTarget", DRW_Coord{}) != 0);
    const std::uint32_t compoundBlock =
        m_writer->defineBlock("CompoundChildren", DRW_Coord{1.0, 2.0, 0.0});
    REQUIRE(compoundBlock != 0);
    REQUIRE(m_writer->beginBlockContent(compoundBlock));

    DRW_Polyline polyline;
    polyline.flags = 1;
    polyline.addVertex(DRW_Vertex(0.0, 0.0, 0.0, 0.0));
    polyline.addVertex(DRW_Vertex(10.0, 0.0, 0.0, 0.0));
    polyline.addVertex(DRW_Vertex(10.0, 5.0, 0.0, 0.0));
    REQUIRE(m_writer->writePolyline(&polyline));

    DRW_Insert insert;
    insert.name = "CompoundTarget";
    insert.basePoint = DRW_Coord{20.0, 30.0, 0.0};
    insert.extPoint = DRW_Coord{0.0, 0.0, 1.0};
    auto attrib = std::make_shared<DRW_Attrib>();
    attrib->basePoint = insert.basePoint;
    attrib->secPoint = insert.basePoint;
    attrib->extPoint = insert.extPoint;
    attrib->height = 2.5;
    attrib->text = "BLOCK_ATTRIB";
    attrib->tag = "BLOCK_TAG";
    attrib->attVersion = 0;
    attrib->m_attributeType = 1;
    insert.attlist.push_back(std::move(attrib));
    REQUIRE(m_writer->writeInsert(&insert));

    REQUIRE(m_writer->endBlockContent());
  }

  void addBlock(const DRW_Block &block) override {
    m_currentBlock = block.name;
    m_blockHandles[block.name] = block.handle;
  }

  void endBlock() override { m_currentBlock.clear(); }

  void addPolyline(const DRW_Polyline &polyline) override {
    if (!m_currentBlock.empty())
      m_polylines[m_currentBlock].push_back(polyline);
  }

  void addInsert(const DRW_Insert &insert) override {
    if (!m_currentBlock.empty())
      m_inserts[m_currentBlock].push_back(insert);
  }

  void
  addDwgFramePublication(const DRW_DwgFramePublication &publication) override {
    m_framePublications.push_back(publication);
  }

private:
  std::string m_currentBlock;
};

class UserBlockMeshPolyfaceRoundTripIface : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  std::uint32_t m_blockRecordHandle{0};
  DRW::DwgBlockWriteResult m_blockResult;
  std::map<std::string, std::vector<DRW_Polyline>> m_polylines;

  void writeBlocks() override {
    REQUIRE(m_writer != nullptr);
    m_blockRecordHandle =
        m_writer->defineBlock("MeshPolyfaceBlock", DRW_Coord{0.0, 0.0, 0.0});
    REQUIRE(m_blockRecordHandle != 0u);
    REQUIRE(m_writer->beginBlockContent(m_blockRecordHandle));

    DRW_Polyline mesh;
    mesh.flags = 16;
    mesh.vertexcount = 2;
    mesh.facecount = 2;
    mesh.addVertex(DRW_Vertex(0.0, 0.0, 0.0, 0.0));
    mesh.addVertex(DRW_Vertex(10.0, 0.0, 1.0, 0.0));
    mesh.addVertex(DRW_Vertex(0.0, 10.0, 2.0, 0.0));
    mesh.addVertex(DRW_Vertex(10.0, 10.0, 3.0, 0.0));
    REQUIRE(m_writer->writePolyline(&mesh));

    DRW_Polyline polyface;
    polyface.flags = 64;
    polyface.vertexcount = 3;
    polyface.facecount = 1;
    DRW_Vertex p1(0.0, 0.0, 0.0, 0.0);
    p1.flags = 64 | 128;
    DRW_Vertex p2(10.0, 0.0, 0.0, 0.0);
    p2.flags = 64 | 128;
    DRW_Vertex p3(0.0, 10.0, 0.0, 0.0);
    p3.flags = 64 | 128;
    DRW_Vertex face;
    face.flags = 128;
    face.vindex1 = 1;
    face.vindex2 = -2;
    face.vindex3 = 3;
    polyface.addVertex(p1);
    polyface.addVertex(p2);
    polyface.addVertex(p3);
    polyface.addVertex(face);
    REQUIRE(m_writer->writePolyline(&polyface));
    REQUIRE(m_writer->endBlockContent());
  }

  bool finalizeDwgWriteStructure() override {
    REQUIRE(m_writer != nullptr);
    return m_writer->getEmittedDwgBlockWriteResult(m_blockResult);
  }

  void addBlock(const DRW_Block &block) override {
    m_currentBlock = block.name;
  }

  void endBlock() override { m_currentBlock.clear(); }

  void addPolyline(const DRW_Polyline &polyline) override {
    if (!m_currentBlock.empty())
      m_polylines[m_currentBlock].push_back(polyline);
  }

private:
  std::string m_currentBlock;
};

class LegacyInsertAttributeRoundTripIface : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  std::vector<DRW_Insert> m_inserts;
  std::vector<DRW_DwgFramePublication> m_framePublications;

  void writeEntities() override {
    if (m_writer == nullptr)
      return;

    DRW_Insert insert;
    // R2000+ INSERT records require an explicit BLOCK_RECORD target.
    insert.name = "*Model_Space";
    insert.blockRecH.ref = DRW::DwgModelSpaceBlockRecordHandle;
    insert.basePoint = DRW_Coord{4.0, 5.0, 0.0};
    insert.extPoint = DRW_Coord{0.0, 0.0, 1.0};
    for (int index = 0; index < 3; ++index) {
      auto attrib = std::make_shared<DRW_Attrib>();
      attrib->basePoint = DRW_Coord{4.0 + index, 5.0, 0.0};
      attrib->secPoint = attrib->basePoint;
      attrib->extPoint = insert.extPoint;
      attrib->height = 2.5;
      attrib->text = "LEGACY_ATTRIB_" + std::to_string(index);
      attrib->tag = "LEGACY_TAG_" + std::to_string(index);
      attrib->attVersion = 0;
      attrib->m_attributeType = 1;
      insert.attlist.push_back(std::move(attrib));
    }
    REQUIRE(m_writer->writeInsert(&insert));
  }

  void addInsert(const DRW_Insert &insert) override {
    m_inserts.push_back(insert);
  }

  void
  addDwgFramePublication(const DRW_DwgFramePublication &publication) override {
    m_framePublications.push_back(publication);
  }
};

