class SidecarSeqEndFailureFilter final : public RS_FilterDXFRW {
public:
  bool failNextSeqEnd{true};
  bool receiptCleared{false};
  std::size_t receiptFrameCount{0};
  DRW::DwgCompoundEntityWriteReceipt receipt;

  void writeEntities() override {
    dwgRW *writer = DwgWriteFailureTestAccess::activeWriter(*this);
    REQUIRE(writer != nullptr);
    if (failNextSeqEnd)
      DwgCompoundWriteTestAccess::failNextSeqEnd(*writer);

    RS_FilterDXFRW::writeEntities();

    receipt = {};
    receiptCleared = !writer->getLastDwgCompoundEntityWriteReceipt(receipt);
    receiptFrameCount = receiptCleared ? 0u : receipt.frames.size();
  }
};

class NativeMeshRoundTripIface : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  DRW_Mesh m_mesh;
  std::vector<DRW_Mesh> m_meshes;

  NativeMeshRoundTripIface() {
    m_mesh.version = 2;
    m_mesh.blendCrease = true;
    m_mesh.subdivisionLevel = 1;
    m_mesh.vertices = {
        {0.0, 0.0, 0.0}, {4.0, 0.0, 0.0}, {4.0, 3.0, 0.0},
        {0.0, 3.0, 0.0}, {2.0, 1.5, 2.0},
    };
    m_mesh.faces = {{0, 1, 2, 3}, {0, 1, 4}, {1, 2, 4}, {2, 3, 4}, {3, 0, 4}};
    m_mesh.edges = {{0, 1}, {1, 2}, {2, 3}, {3, 0},
                    {0, 4}, {1, 4}, {2, 4}, {3, 4}};
    m_mesh.creases = {0.0, 0.25, 0.5, 0.75, 1.0, 1.25, 1.5, 1.75};
    m_mesh.unknown = 7;
  }

  void writeEntities() override {
    if (m_writer != nullptr)
      REQUIRE(m_writer->writeMesh(&m_mesh));
  }

  void addMesh(const DRW_Mesh &mesh) override { m_meshes.push_back(mesh); }
};

class LWPolylineMetadataIface : public EmptyIface {
public:
  dwgRW *m_writer{nullptr};
  std::vector<DRW_LWPolyline> m_lwPolylines;

  void writeEntities() override {
    if (m_writer == nullptr)
      return;

    DRW_LWPolyline pl;
    pl.flags = 1;
    pl.width = 0.25;
    pl.elevation = 7.5;
    pl.thickness = 1.25;
    // Axial extrusion only: RS_FilterDXFRW drops non-axial LWPOLYLINE
    // (strictly 2D LibreCAD polylines). Metadata under test is width /
    // elevation / thickness / vertex ids, not arbitrary OCS normals.
    pl.extPoint = DRW_Coord{0.0, 0.0, 1.0};

    DRW_Vertex2D v0(0.0, 0.0, 0.0);
    v0.stawidth = 0.1;
    v0.endwidth = 0.2;
    v0.identifier = 101;
    DRW_Vertex2D v1(5.0, 0.0, 0.5);
    v1.stawidth = 0.3;
    v1.endwidth = 0.4;
    v1.identifier = 102;
    DRW_Vertex2D v2(5.0, 5.0, 0.0);
    v2.stawidth = 0.5;
    v2.endwidth = 0.6;
    v2.identifier = 103;

    pl.addVertex(v0);
    pl.addVertex(v1);
    pl.addVertex(v2);
    m_writer->writeLWPolyline(&pl);
  }

  void addLWPolyline(const DRW_LWPolyline &pl) override {
    m_lwPolylines.push_back(pl);
  }
};

