  REQUIRE(reloaded.dwgAdvancedMetadata().plotSettings().size() == 1u);
  const auto &decoded = reloaded.dwgAdvancedMetadata().plotSettings().front();
  CHECK(decoded.handle == settings.handle);
  CHECK(decoded.parentHandle == settings.parentHandle);
